display.text:
use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::{self as ast, Expr};
use ruff_python_trivia::{SimpleToken, SimpleTokenKind, SimpleTokenizer};
use ruff_source_file::LineRanges;
use ruff_text_size::{Ranged, TextRange, TextSize};

use crate::checkers::ast::Checker;
use crate::Locator;

/// ## What it does
/// Checks for unnecessary dictionary unpacking operators (`**`).
///
/// ## Why is this bad?
/// Unpacking a dictionary into another dictionary is redundant. The unpacking
/// operator can be removed, making the code more readable.
///
/// ## Example
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, **{"C": 3}}
/// ```
///
/// Use instead:
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, "C": 3}
/// ```
///
/// ## References
/// - [Python documentation: Dictionary displays](https://docs.python.org/3/reference/expressions.html#dictionary-displays)
#[derive(ViolationMetadata)]
pub(crate) struct UnnecessarySpread;

impl Violation for UnnecessarySpread {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Unnecessary spread `**`".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove unnecessary dict".to_string())
    }
}

/// PIE800
pub(crate) fn unnecessary_spread(checker: &mut Checker, dict: &ast::ExprDict) {
    // The first "end" is the start of the dictionary, immediately following the open bracket.
    let mut prev_end = dict.start() + TextSize::from(1);
    for ast::DictItem { key, value } in dict {
        if key.is_none() {
            // We only care about when the key is None which indicates a spread `**`
            // inside a dict.
            if let Expr::Dict(inner) = value {
                let mut diagnostic = Diagnostic::new(UnnecessarySpread, value.range());
                if let Some(fix) = unnecessary_spread_fix(inner, prev_end, checker.locator()) {
                    diagnostic.set_fix(fix);
                }
                checker.diagnostics.push(diagnostic);
            }
        }
        prev_end = value.end();
    }
}

/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    let source = locator.contents();
    let source_len = locator.text_len();
    let search_start = locator.floor_char_boundary(prev_end);
    if source.is_empty() {
        return None;
    }

    let dict_start = dict.start();

    let mut doublestar: Option<SimpleToken> = None;
    for tok in SimpleTokenizer::starts_at(search_start, source) {
        if tok.end() <= source_len {
            if tok.kind() == SimpleTokenKind::DoubleStar {
                if !tok.range().is_empty() && !locator.contains_line_break(tok.range()) {
                    doublestar = Some(tok);
                    break;
                }
            }
        }
    }

    let doublestar = doublestar?;
    if doublestar.start() > dict_start {
        return None;
    }

    // Determine whether the dictionary is wrapped in parentheses. The
    // parentheses have to be removed along with the `**` operator, otherwise
    // the fix would introduce a syntax error.
    // Ex) `**({"a": 1})`
    let mut leading_parens = 0usize;
    let mut leading_lparens = Vec::new();
    if doublestar.end() < dict_start {
        for tok in SimpleTokenizer::starts_at(doublestar.end(), source) {
            if tok.start() >= dict_start {
                break;
            }
            match tok.kind() {
                SimpleTokenKind::LParen => leading_lparens.push(tok),
                kind if kind.is_trivia() => {}
                // Anything else between the `**` and the dictionary is
                // unexpected; bail out of the fix.
                _ => return None,
            }
        }
        leading_parens = leading_lparens.len();
    }

    // Collect the closing parentheses that match the leading parentheses.
    let mut trailing_rparens: Vec<SimpleToken> = Vec::new();
    if leading_parens > 0 {
        if let Some(last) = dict.iter_values().last() {
            let trailing_start = last.end();
            let mut seen_rbrace = false;
            for tok in SimpleTokenizer::starts_at(trailing_start, source).skip_trivia() {
                if !seen_rbrace && tok.start() >= dict.end() {
                    // We've scanned past the closing brace of the dictionary
                    // without seeing it; bail out.
                    break;
                }
                match tok.kind() {
                    SimpleTokenKind::RBrace => {
                        seen_rbrace = true;
                    }
                    SimpleTokenKind::RParen if seen_rbrace => {
                        trailing_rparens.push(tok);
                        if trailing_rparens.len() == leading_parens {
                            break;
                        }
                    }
                    // Skip any other tokens before the closing brace (e.g., a
                    // trailing comma, or the closing parenthesis of a
                    // parenthesized value like `(a := 1)` whose range does not
                    // include the parentheses).
                    _ if !seen_rbrace => {}
                    // Stop at any unexpected token after the closing brace.
                    _ => break,
                }
            }
        } else {
            for tok in SimpleTokenizer::starts_at(dict.end(), source).skip_trivia() {
                match tok.kind() {
                    SimpleTokenKind::RParen => {
                        trailing_rparens.push(tok);
                        if trailing_rparens.len() == leading_parens {
                            break;
                        }
                    }
                    _ => break,
                }
            }
        }
        if trailing_rparens.len() != leading_parens {
            return None;
        }
    }

    if let Some(last) = dict.iter_values().last() {
        // Ex) `**{a: 1, b: 2}` or `**(  # Comment
        //                         {a: 1, b: 2}  # Comment
        //                     )`
        let mut edits = vec![Edit::range_deletion(doublestar.range())];
        if leading_parens > 0 {
            edits.extend(
                leading_lparens
                    .iter()
                    .map(|tok| Edit::range_deletion(tok.range())),
            );
        }
        // Delete the opening brace of the dictionary.
        edits.push(Edit::range_deletion(TextRange::at(
            dict.start(),
            TextSize::of('{'),
        )));
        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::Comma => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RBrace => {
                    edits.push(Edit::range_deletion(tok.range()));
                    break;
                }
                _ => {}
            }
        }
        edits.extend(
            trailing_rparens
                .iter()
                .map(|tok| Edit::range_deletion(tok.range())),
        );
        Some(Fix::safe_edits(edits.remove(0), edits))
    } else {
        // Ex) `**{}` or `**({})`
        let mut edits = vec![Edit::range_deletion(doublestar.range())];
        if leading_parens > 0 {
            edits.extend(
                leading_lparens
                    .iter()
                    .map(|tok| Edit::range_deletion(tok.range())),
            );
            edits.push(Edit::deletion(dict.start(), dict.end()));
            edits.extend(
                trailing_rparens
                    .iter()
                    .map(|tok| Edit::range_deletion(tok.range())),
            );
            Some(Fix::safe_edits(edits.remove(0), edits))
        } else {
            Some(Fix::safe_edit(Edit::deletion(
                doublestar.start(),
                dict.end(),
            )))
        }
    }
}

